DASHBOARD_JS: str = "\nmermaid.initialize({ startOnLoad: false, theme: 'dark' });\n\nasync function renderVisibleDiagrams(panel) {\n    const nodes = Array.from(panel.querySelectorAll('.mermaid:not([data-processed])'))\n        .filter(node => node.getBoundingClientRect().width > 0);\n    if (!nodes.length) return;\n    try {\n        await mermaid.run({ nodes });\n    } catch (error) {\n        const message = document.createElement('p');\n        message.setAttribute('role', 'alert');\n        message.textContent = 'Diagram rendering failed: ' + String(error);\n        panel.appendChild(message);\n        console.error(error);\n    }\n}\n\nfunction switchTab(event, tabId) {\n    event.preventDefault();\n    const selectedTab = document.getElementById(tabId);\n    if (!selectedTab) return;\n    document.querySelectorAll('.tab-content').forEach(panel => {\n        panel.classList.toggle('active', panel === selectedTab);\n    });\n    document.querySelectorAll('.tab-button').forEach(button => {\n        const selected = button.getAttribute('aria-controls') === tabId;\n        button.classList.toggle('active', selected);\n        button.setAttribute('aria-selected', String(selected));\n        button.tabIndex = selected ? 0 : -1;\n    });\n    requestAnimationFrame(() => renderVisibleDiagrams(selectedTab));\n}\n\nfunction filterTable(input, tableId) {\n    const table = document.getElementById(tableId);\n    if (!table) return;\n    const filter = input.value.toUpperCase();\n    for (const row of table.querySelectorAll('tbody tr')) {\n        row.style.display = row.textContent.toUpperCase().includes(filter) ? '' : 'none';\n    }\n}\n\ndocument.querySelectorAll('.tab-content').forEach(panel => {\n    panel.setAttribute('role', 'tabpanel');\n    panel.setAttribute('aria-labelledby', 'tab-' + panel.id);\n});\ndocument.addEventListener('keydown', event => {\n    if (!(event.target instanceof Element) || !event.target.closest('.tab-button')) return;\n    const buttons = Array.from(document.querySelectorAll('.tab-button'));\n    const current = buttons.indexOf(event.target.closest('.tab-button'));\n    let next;\n    if (event.key === 'ArrowRight') next = (current + 1) % buttons.length;\n    else if (event.key === 'ArrowLeft') next = (current - 1 + buttons.length) % buttons.length;\n    else if (event.key === 'Home') next = 0;\n    else if (event.key === 'End') next = buttons.length - 1;\n    else return;\n    event.preventDefault();\n    buttons[next].focus();\n    buttons[next].click();\n});\nrequestAnimationFrame(() => renderVisibleDiagrams(document.querySelector('.tab-content.active')));\n"
